Definition AFieldsOwn (LB : list block) (em : gmap Z elt) : Prop :=
  forall e d, em !! e = Some d ->
    exists p, In (p, e, esize d) LB /\ esize d = elem_block_size (el_name d) (el_value d).

Section HCW.
