(* [comment removed for export] *)
Lemma AFieldsC_ext : forall m m' Fa S L ns ls em,
  AFieldsC m Fa S L ns ls em ->
  (forall A cs, rw_cells asegs m A cs ->
     (Fa <= A /\ A + Z.of_nat (cells_size cs) <= Fa + 48)
     \/ (exists e d, em !! e = Some d /\ e <= A /\ A + Z.of_nat (cells_size cs) <= e + esize d) ->
     rw_cells asegs m' A cs) ->
  (forall e d, em !! e = Some d -> addressable m e (esize d) -> addressable m' e (esize d)) ->
  (accessible m Fa 48 -> accessible m' Fa 48) ->
  AFieldsC m' Fa S L ns ls em.
Proof.
  intros m m' Fa S L ns ls em FC TC TA TH.
  pose proof FC as (NC & LC & EC & OK & SO & DL & SL & LE' & EOK & ESH & HA & HS).
  split.
  { intros a nd La. destruct (NC a nd La) as [WF [pad C]]. split; [exact WF|]. exists pad.
    apply TC; [exact C|]. rewrite NodeCells_size.
    destruct (AFieldsC_node_in _ _ _ _ _ _ _ _ _ FC La) as [->|(d & Ld & _)]; [left; lia| right].
    exists (a - 16), d. pose proof (esize_ge d). split; [exact Ld| lia]. }
  split.
  { intros a n La. destruct (LC a n La) as [WF C]. split; [exact WF|].
    apply TC; [exact C|]. rewrite LNodeCells_size.
    destruct (AFieldsC_lnode_in _ _ _ _ _ _ _ _ _ FC La) as [->|(d & Ld & _)]; [left; lia| right].
    exists a, d. pose proof (esize_ge d). split; [exact Ld| lia]. }
  split.
  { intros e d Ld. apply TC; [exact (EC e d Ld)|]. right. exists e, d. split; [exact Ld|]. rewrite ValCells_size. lia. }
  split; [exact OK|]. split; [exact SO|]. split; [exact DL|]. split; [exact SL|]. split; [exact LE'|].
  split; [exact EOK|].
  split. { intros e d Ld. apply TA; [exact Ld| exact (ESH e d Ld)]. }
  split; [| exact HS]. destruct HA as (AP & AL & AC). split; [exact AP|]. split; [exact AL| exact (TH AC)].
Qed.

