(* [comment removed for export] *)
Lemma AFieldsOwn_aobj : forall LB LF em e d, AFieldsOwn LB em -> em !! e = Some d -> aobj LB LF e (esize d).
Proof. intros LB LF em e d OWN L. destruct (OWN e d L) as (p & IN & _). eapply aobj_block; [exact IN| lia| lia]. Qed.

(* [comment removed for export] *)
Lemma AFieldsC_apres : forall s LB m0 LF m1 SP m m' Fa S L ns ls em,
  as_RHEAP H s LB m0 -> as_RFS H LF m1 ->
  AFieldsC m Fa S L ns ls em -> AFieldsOwn LB em -> aobj LB LF Fa 48 ->
  apres H LB SP m m' -> AFieldsC m' Fa S L ns ls em.
Proof.
  intros s LB m0 LF m1 SP m m' Fa S L ns ls em RH RF FC OWN AOH AP.
  eapply AFieldsC_ext; [exact FC| | |].
  - intros A cs C [[H1 H2]|(e & d & Ld & H1 & H2)].
    + eapply (apres_rw_cells H); [exact AP| exact C|].
      eapply (aobj_client H HH); [exact RH| exact RF| eapply aobj_sub; [exact AOH| exact H1| exact H2]].
    + destruct (OWN e d Ld) as (p & IN & _).
      eapply (apres_rw_cells H); [exact AP| exact C|]. eapply aclient_range_block; [exact IN| exact H1| exact H2].
  - intros e d Ld AD. destruct (OWN e d Ld) as (p & IN & _). eapply (apres_addressable H); [exact AP| exact AD| exact IN].
  - intros AC. eapply (aobj_apres_accessible H HH); [exact RH| exact RF| exact AOH| exact AP| exact AC| lia| lia].
Qed.
