(* [comment removed for export] *)
Lemma fresh_vs_aobj0 : forall LF s' L' m' m1 p A n O k,
  as_RHEAP H s' ((p, A, n) :: L') m' -> as_RFS H LF m1 -> aobj L' LF O k -> 0 <= k -> O + k <= A \/ A + n <= O.
Proof.
  intros LF s' L' m' m1 p A n O k HP RF AO Hk.
  pose proof (ah_blocks H HH _ _ _ (p, A, n) HP (or_introl eq_refl)) as (R1 & R2 & R3 & R4 & R5 & R6 & R7). cbn in R1, R2, R3, R4, R5, R6, R7.
  destruct AO as [(b & Hb & K1 & K2)|(f & Hf & K1 & K2)].
  - pose proof (ah_nodup H HH _ _ _ HP) as ND. cbn in ND. inversion ND as [|x l NI ND']; subst.
    assert (NE : blk_id (p, A, n) <> blk_id b).
    { cbn. intros E. apply NI. apply in_map_iff. exists b. split; [symmetry; exact E| exact Hb]. }
    destruct (ah_disj H HH _ _ _ (p, A, n) b HP (or_introl eq_refl) (or_intror Hb) NE) as [D|D]; cbn in D; lia.
  - pose proof (proj2 (ah_RFS_range H HH _ _ RF) f Hf) as (K & Q1 & Q2 & Q3 & Q4). unfold AFS_HDR, AFS_SIZE in *. lia.
Qed.

