(* [comment removed for export] *)
(* [comment removed for export] *)

Definition INS_STACK : Z := 160 + AOPNEW_STACK.

Section SR.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.
  Hypothesis FS0 : stack_malloc_stmt H 0 P_A_FS_MALLOC_0.

  Definition ins_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : as_St H) (LB : list block) (LF : list fframe) (Fa f ecA : Z) (name value : list byte) (L : list Z) (em : gmap Z elt)
      (lo B shi : Z) (m : mem) (mo : Model) : config -> Prop :=
    fun c => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (errv' : word) (s' : as_St H) (p : bptr) (A : Z) pad tl S' L' ns' ls'
                    (XS : list (Z * Z)),
      as_VIS H s' (cfg_ms c) = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                                  F (ret_pc ra) fc None m' (seg_rom asegs)
      /\ as_AKREL H s' c /\ as_MPRES H mo (cfg_model c)
      /\ mem_inv asegs m' /\ stk asegs m' lo (bv_unsigned sp)
      /\ rw_cells asegs m' (errno_addr tp) [C4 errv'] /\ as_rauxv_ok H m' B
      /\ rblock_range A (elem_block_size name (trim value))
      /\ as_RHEAP H s' ((p, A, elem_block_size name (trim value)) :: LB) m'
      /\ AFieldsC m' Fa S' L' ns' ls' (<[A := mkElt f name (trim value) pad tl]> em) /\ (A + 16) ∈ S' /\ A ∈ L'
      /\ AFieldsOwn ((p, A, elem_block_size name (trim value)) :: LB) (<[A := mkElt f name (trim value) pad tl]> em)
      /\ rw_cells asegs m' ecA (ErrCodeCells EC_clear)
      /\ Forall (fs_scratch H LF) XS
      /\ xpres H LB (bv_unsigned sp) (((ecA, ecA + 24) :: (Fa, Fa + 48) :: elemsW L) ++ XS) m m'
      (* [comment removed for export] *)
      /\ as_RFS H LF m' /\ ACONST m' /\ stack0 m' lo shi /\ accessible m' ecA 24
      /\ as_AL H s' >= as_AL H s - as_Cm H (elem_block_size name (trim value)).

  Definition ins_stmt_at (entry : Z) (off : Z) : Prop :=
    forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
           (F : bvmap 5 word) (fc : bv 32) (msF : machine_state) (m : mem) (mo : Model)
           (s : as_St H) (LB : list block) (LF : list fframe) (P f np vp ecA : Z) (name value : list byte) (E0 : ecv)
           (S L : list Z) (ns : NS) (ls : LS) (em : gmap Z elt) (lo B shi : Z) (errv : word),
      as_VIS H s msF = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                          F (Z_to_bv 64 entry) fc None m (seg_rom asegs) ->
      a0 = Z_to_bv 64 P -> a1 = Z_to_bv 64 f -> a2 = Z_to_bv 64 np -> a3 = Z_to_bv 64 (zlength name) ->
      a4 = Z_to_bv 64 vp -> a5 = Z_to_bv 64 (zlength value) -> a6 = Z_to_bv 64 ecA ->
      AFieldsC m (P + off) S L ns ls em -> AFieldsOwn LB em ->
      bytes_at asegs m np name -> bytes_at asegs m vp value -> vp + zlength value < 2^64 ->
      zlength name <= 65533 -> zlength value <= 65533 -> 0 <= f < 2^16 ->
      rw_cells asegs m ecA (ErrCodeCells E0) ->
      (ecA + 24 <= P + off \/ P + off + 48 <= ecA) -> (np + zlength name <= ecA \/ ecA + 24 <= np) -> (vp + zlength value <= ecA \/ ecA + 24 <= vp) ->
      as_RHEAP H s LB m -> as_AKREL H s (mkCfg msF mo) ->
      lb_bytes LB + (zlength name + zlength value + 67) <= as_LIVE_MAX H -> Z.of_nat (length LB) + 1 <= as_LIVE_CNT_MAX H ->
      as_rauxv_ok H m B -> bv_unsigned sp <= B ->
      stk asegs m lo (bv_unsigned sp) -> aceil <= lo -> lo <= bv_unsigned sp - INS_STACK ->
      rw_cells asegs m (errno_addr tp) [C4 errv] -> mem_inv asegs m -> tp = Z_to_bv 64 ATP ->
      bv_unsigned sp mod 16 = 0 ->
      (* [comment removed for export] *)
      0 <= P -> aobj LB LF (P + off) 48 ->
      aobj LB LF ecA 24 -> ecA mod 8 = 0 -> accessible m ecA 24 ->
      (forall e d, em !! e = Some d -> ecA + 24 <= e \/ e + esize d <= ecA) ->
      aobj LB LF np (zlength name) -> accessible m np (zlength name) ->
      aobj LB LF vp (zlength value) -> accessible m vp (zlength value) ->
      as_RFS H LF m -> (length LF < AFS_MAXLIVE)%nat -> ACONST m ->
      stack0 m lo shi -> bv_unsigned sp <= shi ->
      as_Cm H (elem_block_size name (trim value)) <= as_AL H s ->
      as_SR H (ins_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB LF (P + off) f ecA name value L em lo B shi m mo)
        (mkCfg msF mo).

  Definition ins_stmt : Prop := ins_stmt_at P_A_FIELDS_INSERT 0.
  Definition ofi_stmt : Prop := ins_stmt_at P_A_ON_FIELD_IMPL 80.
Scheme kc__7 := Elimination for LinuxProcessSemantics.LinuxProcessSem.Run.config Sort Prop.
Scheme kc__8 := Elimination for Corelib.Init.Specif.sumbool Sort Prop.

